sp_angular_provider.script:
function spReferenceElementV2() {

	return {
		restrict: "E",
        replace: true,
        scope: {
            ed: "=?",
            field: "=",
            refTable: "=?",
            refId: "=?",
            snOptions: "=?",
            snOnBlur: "&",
            snOnClose: "&",
            minimumInputLength: "@",
            snDisabled: "=",
            dropdownCssClass: "@",
            formatResultCssClass: "&",
            displayColumn: "@",
            recordValues: "&",
            getGlideForm: "&glideForm",
            domain: "@",
            snSelectWidth: "@",
            labelId: "@?",
			getColumns: "&",
			snChange: "&",
			onChange: "&"
        },
        template: '<div><input type="text" id="sp_formfield_{{::field.name}}" name="{{::field.name}}" ng-disabled="snDisabled" class="input-field-min-width" aria-hidden="true" ng-model="field.stagedValue" ng-change="onChange()"/><div class="row"><div class="col-md-4" ng-repeat="column in ::getColumns(field)"><div class="form-check" ng-repeat="entry in column"><input class="form-check-input" type="checkbox"/><label class="form-check-label">{{entry.label}}</label></div></div></div>',
		link: function(scope, element) {
			var retColumns = null;
			scope.getColumns = function(field) {
				if (retColumns != null) {
					return retColumns;
				}
				retColumns = [];
				if (field.choices && field.choices.length > 0) {
					var startIndex = 0;
					var choicesLen = field.choices.length;
					if (field.choices[0].value == '') {
						startIndex = 1;
						choicesLen -= 1;
					}
					var numRows = Math.ceil(choicesLen / 3.0);
					for (var colIndex = 0; colIndex < 3; colIndex++) {
						var column = [];
						for (var rowIndex = 0; rowIndex < numRows; rowIndex++) {
							var choiceIndex = startIndex + colIndex * numRows;
							column.push(field.choices[choiceIndex + rowIndex]);
						}
						retColumns.push(column);
					}
				}
				console.log("GET CHOICES");
				console.log(retColumns);
				return retColumns;
			};

			scope.onChange = function() {
				console.log("ON CHANGE:");
				scope.field.value = scope.field.stagedValue;
				console.log(scope.field);
			};

			console.log(scope.field);
			console.log("Field show_checkboxes attribute: " + scope.field.attributes.show_checkboxes);
			var $el = element;
			var column_class = "col-md-2";
			while ($el) {
				if ($el.hasClass("col-md-12")) {
					column_class = "col-md-4";
					break;
				}
				else if ($el.hasClass("col-md-6")) {
					break;
				}
				$el = $el.parent();
			}
			console.log("Number of checkbox columns = " + column_class);
		}
	}
}
